 const assignmentNotice=({EMPLOYEE_PROFILE_NOT_LINKED:"حسابك غير مرتبط بسجل موظف. اطلب من الإدارة ربط بريد الحساب بسجل الموظف.",NO_BRANCH_ASSIGNMENT:"لم يتم تعيين فرع لحسابك. اطلب من الإدارة تحديد فرع العمل.",NO_MATCHING_TABLE_ASSIGNMENT:"لا توجد طاولة معيّنة لحسابك في فرعك. تحقق من تعيين النادل على الطاولة.",ASSIGNED:""} as Record<string,string>)[assignmentStatus]??"";
 useEffect(()=>{if(!dining||data.role!=="waiter")return;let active=true;const load=async()=>{try{const response=await fetch("/api/restaurant/assigned-service?tenantId="+encodeURIComponent(data.tenantId),{cache:"no-store"});const result=await response.json();if(!response.ok)throw Error(result.code);if(active){setAssigned({tables:result.tables??[],calls:result.calls??[]});setAssignmentStatus(result.assignmentStatus??"");setAssignedError("");}}catch(error){if(active)setAssignedError(String(error));}};void load();const interval=setInterval(()=>void load(),15000);const onFocus=()=>void load();const onVisibility=()=>{if(document.visibilityState==="visible")void load();};window.addEventListener("focus",onFocus);document.addEventListener("visibilitychange",onVisibility);return()=>{active=false;clearInterval(interval);window.removeEventListener("focus",onFocus);document.removeEventListener("visibilitychange",onVisibility);};},[data.tenantId,dining]);
 const audioRef=useRef<AudioContext|null>(null),lastAlertRef=useRef<number|null>(null);
 function playAlert(){const ctx=audioRef.current;if(!ctx||ctx.state!=="running")return;for(const [index,frequency] of [880,1175,880].entries()){const oscillator=ctx.createOscillator(),gain=ctx.createGain(),start=ctx.currentTime+index*0.24;oscillator.type="square";oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(0.001,start);gain.gain.exponentialRampToValueAtTime(0.32,start+0.025);gain.gain.exponentialRampToValueAtTime(0.001,start+0.2);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start(start);oscillator.stop(start+0.21);}}
 async function toggleSound(){if(soundEnabled){setSoundEnabled(false);lastAlertRef.current=null;await audioRef.current?.suspend();return;}try{const ctx=audioRef.current??new AudioContext();audioRef.current=ctx;await ctx.resume();lastAlertRef.current=live?(audibleCount):null;setSoundEnabled(true);playAlert();}catch{setLiveError(tr("تعذر تشغيل الصوت. تأكد من سماح المتصفح بتشغيل الصوت.","Could not play sound. Check your browser audio permissions.","Impossible de lire le son. Vérifiez les autorisations audio du navigateur."));}}
 useEffect(()=>{if(!soundEnabled)return;const count=audibleCount;lastAlertRef.current=count;if(count<=0)return;const timer=setInterval(()=>{if(audioRef.current?.state==="running")playAlert();},12000);return()=>clearInterval(timer);},[soundEnabled,audibleCount]);
 useEffect(()=>()=>{void audioRef.current?.close();},[]);
