 async function switchTenant(nextTenant:string){
  if(nextTenant===data.tenantId||busy)return;
  setBusy(true);setMessage("");
  try{
   const response=await fetch("/api/tenant/active",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({tenantId:nextTenant})});
   if(!response.ok)throw Error("FORBIDDEN");
   const result=await response.json() as {path:string};
   if(typeof result.path!=="string"||!result.path.startsWith("/"))throw Error("INVALID_PATH");
   router.replace(result.path);
   router.refresh();
  }catch{setMessage("تعذر تغيير النشاط. تحقق من الصلاحيات وأعد المحاولة.");}
  finally{setBusy(false);}
 }
