 async function createBranch(event:FormEvent<HTMLFormElement>){event.preventDefault();if(busy)return;const form=event.currentTarget,f=new FormData(form);setBusy(true);setMessage("");try{const r=await fetch("/api/restaurant/branches",{method:editingBranch?"PATCH":"POST",headers:{"content-type":"application/json","x-foon-tenant":data.tenantId},body:JSON.stringify({...(editingBranch?{id:editingBranch.id,version:editingBranch.version}:{}),name:f.get("name"),slug:f.get("slug")})});const result=await r.json();if(!r.ok){setMessage(result.code==="PLAN_FEATURE_REQUIRED"?tr("تعدد الفروع غير متاح في الباقة الحالية.","Multiple branches are not included in your plan.","Votre abonnement ne permet pas plusieurs succursales."):result.code==="BRANCH_SLUG_EXISTS"?tr("رابط الفرع مستخدم مسبقاً.","This branch URL is already in use.","Cette URL de succursale est déjà utilisée."):result.code==="CONFLICT"?tr("تغيّرت بيانات الفرع. حدّث الصفحة وأعد المحاولة.","Branch details changed. Refresh and try again.","Les données de la succursale ont changé. Actualisez et réessayez."):tr("تعذر حفظ الفرع. راجع البيانات وحاول مجدداً.","Could not save the branch. Check the details and retry.","Impossible d’enregistrer la succursale. Vérifiez les informations."));return;}form.reset();setMessage(editingBranch?tr("تم تحديث الفرع.","Branch updated.","Succursale mise à jour."):tr("تم إنشاء الفرع.","Branch created.","Succursale créée."));setEditingBranch(null);changed();}catch{setMessage(tr("تعذر الاتصال بالخادم.","Could not connect to the server.","Connexion au serveur impossible."));}finally{setBusy(false);}}
