 const tr=(ar:string,en:string,fr:string)=>{
  if(uiLanguage==="en")return dining?en:en.replaceAll("Kitchen team follow-up","Operations team follow-up").replaceAll("Table / channel","Order channel").replaceAll("Preparing",services?"In progress":"Being packed");
  if(uiLanguage==="fr")return dining?fr:fr.replaceAll("Suivi de l’équipe de cuisine","Suivi de l’équipe opérationnelle").replaceAll("Table / canal","Canal de commande").replaceAll("En préparation",services?"En cours":"En conditionnement");
  if(data.activityCode==="restaurant")return ar;
  return ar.replaceAll("للمطعم","للنشاط").replaceAll("المطعم",activityName[0]).replaceAll("مطعمك",activityName[0]).replaceAll("فريق المطبخ",dining?"فريق المطبخ":"فريق التشغيل").replaceAll("قيد التحضير",dining?"قيد التحضير":services?"قيد التنفيذ":"قيد التجهيز").replaceAll("الطاولة / القناة",dining?"الطاولة / القناة":"قناة الطلب");
 };
 const navTitle=(key:Section,label:string)=>key==="menu"&&data.activityCode!=="restaurant"?(services?tr("دليل الخدمات","Service catalog","Catalogue des services"):data.activityCode==="cafe"?tr("قائمة المشروبات والمأكولات","Drinks and food menu","Carte des boissons et plats"):tr("المنتجات والأقسام","Products and categories","Produits et catégories")):key==="reservations"&&!dining?tr("المواعيد","Appointments","Rendez-vous"):uiLanguage!=="ar"?(sectionTranslations[key]?.[uiLanguage]??label):key==="menu"&&data.activityCode==="grocery"?translateUi("المنتجات والأقسام"):key==="storefront"&&data.activityCode==="grocery"?"هوية واجهة السوبر ماركت":label;
 const navigation=<><div className="restaurantSideBrand"><span><MerchantIcon name="menu"/></span><div><b>FOON</b><small>{uiLanguage==="en"?"Business operations":uiLanguage==="fr"?"Gestion des activités":data.activityCode==="grocery"?"نظام تشغيل السوبر ماركت":"نظام تشغيل الأنشطة"}</small></div></div><p className="restaurantNavLabel">{uiLanguage==="en"?"Workspace":uiLanguage==="fr"?"Espace de travail":translateUi("مساحة العمل")}</p><nav aria-label={tr("أقسام النشاط","Business sections","Sections de l’activité")}>{visible.map(m=><button key={m.key} type="button" aria-current={active===m.key?"page":undefined} data-action-state={navCount(m.key)>0?"pending":undefined} onClick={()=>navigate(m.key)}><MerchantIcon name={m.icon}/><span>{navTitle(m.key,m.label)}</span>{navCount(m.key)>0&&<small className="restaurantNavAttentionCount" aria-label={tr("عناصر تحتاج إجراء","Items needing action","Éléments nécessitant une action")}>{navCount(m.key)}</small>}{m.feature&&!granted(m.key==="menu"&&services?"catalog":m.key==="reservations"&&!dining?"quotes":m.feature)&&<small title={tr("غير مشمول في الباقة","Not included in plan","Non inclus dans l’abonnement")}>{tr("مقفل","Locked","Verrouillé")}</small>}</button>)}</nav><div className="restaurantSideFooter">{canManage&&<button className="restaurantPlanShortcut" type="button" onClick={()=>navigate("subscription")}><MerchantIcon name="shield"/><span><small>{tr("الاشتراك الحالي","Current subscription","Abonnement actuel")}</small><b>{(uiLanguage==="en"?data.subscription?.nameEn:uiLanguage==="fr"?data.subscription?.nameFr:data.subscription?.name)??tr("لم تعيّن باقة","No plan assigned","Aucun abonnement attribué")}</b></span><MerchantIcon name="arrow"/></button>}<Link href={data.adminAccess?"/admin/tenants":"/account"}>{data.adminAccess?tr("العودة إلى إدارة المنصة","Back to platform admin","Retour à l’administration"):tr("حسابي","My account","Mon compte")}<MerchantIcon name="arrow"/></Link></div></>;
 const branchList=<div className="restaurantBranchList">{shownBranches.length?shownBranches.map(b=><div key={b.id}><i data-enabled={b.enabled}/><span><b>{b.name}</b><small>{b.slug==="main"?tr("الفرع الرئيسي","Main branch","Succursale principale"):b.slug}</small></span><em>{b.enabled?tr("مفعّل","Enabled","Activée"):tr("معطّل","Disabled","Désactivée")}</em>{active==="branches"&&canManage&&<div className="restaurantBranchActions"><button disabled={busy} onClick={()=>setEditingBranch(b)}>{tr("تعديل","Edit","Modifier")}</button><button disabled={busy} onClick={()=>void toggleBranch(b)}>{b.enabled?tr("إيقاف","Disable","Désactiver"):tr("تفعيل","Enable","Activer")}</button></div>}</div>):<p>{tr("لا توجد فروع ضمن الاختيار الحالي.","No branches match the current selection.","Aucune succursale pour la sélection actuelle.")}</p>}</div>;
