   <section className="restaurantHero"><div className="restaurantHeroTop"><div><small>{tr("مساحة المطعم التشغيلية","Business workspace","Espace de gestion")}</small><h2>{data.activityCode==="restaurant"?tr("لوحة التشغيل المباشر","Live operations dashboard","Tableau de bord en direct"):tr("لوحة تشغيل "+activityName[0],activityName[1]+" operations", "Gestion : "+activityName[2])}</h2><p>{tr("تابع مطعمك وفروعك وإعداداته من مساحة واحدة واضحة.","Manage your business, branches and settings in one place.","Gérez votre activité, vos succursales et vos paramètres au même endroit.")}</p></div><div className="restaurantHeroActions"><span>{data.subscription?.status==="active"?tr("الاشتراك نشط","Subscription active","Abonnement actif"):data.subscription?tr("الاشتراك ","Subscription: ","Abonnement : ")+(statuses[data.subscription.status]??data.subscription.status):tr("مساحة العمل","Workspace","Espace de travail")}</span><Link className="restaurantPrimary" href={publicStorefrontUrl(data.slug)}><MerchantIcon name="menu"/>{tr("فتح واجهة المطعم","Open storefront","Ouvrir la vitrine")}</Link></div></div><div className="restaurantHeroStats">{[[tr("طلبات تحتاج متابعة","Orders needing attention","Commandes à traiter"),live?.summary.newOrders,tr("طلبات جديدة","New orders","Nouvelles commandes")],[tr("قيد التحضير","Preparing","En préparation"),live?.summary.preparing,tr("متابعة فريق المطبخ","Kitchen team follow-up","Suivi de l’équipe de cuisine")],[tr("جاهزة للتسليم","Ready for handoff","Prêtes à remettre"),live?.summary.ready,tr("بانتظار التسليم","Awaiting handoff","En attente de remise")]].map(([title,count,note])=><div key={String(title)}><p>{title}</p><strong>{count??"—"}</strong><small>{note}</small></div>)}</div></section>
